using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Live index of every enabled <see cref="BoardComponent"/> on the board. Fire and
/// Charge both need "a random component" or "the N nearest" several times a second
/// across multiple sources, which is far too hot for a per-query FindObjectsByType.
/// Components register themselves on enable and drop out on disable, so the list
/// survives additive board loads without any scene wiring.
/// </summary>
public static class BoardComponentRegistry
{
    private static readonly List<BoardComponent> components = new List<BoardComponent>();
    private static readonly List<BoardComponent> queryBuffer = new List<BoardComponent>();

    public static IReadOnlyList<BoardComponent> All => components;

    public static void Register(BoardComponent component)
    {
        if (component == null || components.Contains(component))
        {
            return;
        }

        components.Add(component);
    }

    public static void Unregister(BoardComponent component)
    {
        components.Remove(component);
    }

    /// <summary>
    /// A random component that can be targeted by status effects, or null if the
    /// board has none. Flippers and Portals are always excluded.
    /// </summary>
    public static BoardComponent GetRandom(BoardComponent exclude = null)
    {
        BuildCandidates(exclude);
        if (queryBuffer.Count == 0)
        {
            return null;
        }

        return queryBuffer[Random.Range(0, queryBuffer.Count)];
    }

    /// <summary>
    /// Up to <paramref name="count"/> distinct random components, never repeating.
    /// Fewer are returned when the board cannot supply that many.
    /// </summary>
    public static List<BoardComponent> GetRandom(int count, BoardComponent exclude = null)
    {
        BuildCandidates(exclude);

        List<BoardComponent> picks = new List<BoardComponent>();
        int wanted = Mathf.Min(count, queryBuffer.Count);
        for (int i = 0; i < wanted; i++)
        {
            int index = Random.Range(i, queryBuffer.Count);
            (queryBuffer[i], queryBuffer[index]) = (queryBuffer[index], queryBuffer[i]);
            picks.Add(queryBuffer[i]);
        }

        return picks;
    }

    /// <summary>
    /// The <paramref name="count"/> components nearest to <paramref name="origin"/>
    /// within <paramref name="maxDistance"/>, closest first.
    /// </summary>
    public static List<BoardComponent> GetNearest(
        Vector3 origin, int count, float maxDistance, BoardComponent exclude = null)
    {
        BuildCandidates(exclude);

        float maxDistanceSquared = maxDistance * maxDistance;
        List<BoardComponent> nearest = new List<BoardComponent>();
        foreach (BoardComponent component in queryBuffer)
        {
            float distanceSquared =
                (component.transform.position - origin).sqrMagnitude;
            if (distanceSquared <= maxDistanceSquared)
            {
                nearest.Add(component);
            }
        }

        nearest.Sort((a, b) =>
            (a.transform.position - origin).sqrMagnitude.CompareTo(
                (b.transform.position - origin).sqrMagnitude));

        if (nearest.Count > count)
        {
            nearest.RemoveRange(count, nearest.Count - count);
        }

        return nearest;
    }

    /// <summary>
    /// Refills the shared scratch list with every component eligible to be targeted
    /// by a status effect. Destroyed entries are pruned as they are found.
    /// </summary>
    private static void BuildCandidates(BoardComponent exclude)
    {
        queryBuffer.Clear();

        for (int i = components.Count - 1; i >= 0; i--)
        {
            BoardComponent component = components[i];
            if (component == null)
            {
                components.RemoveAt(i);
                continue;
            }

            if (component == exclude || !StatusTargeting.CanBeTargeted(component))
            {
                continue;
            }

            queryBuffer.Add(component);
        }
    }
}
